	Gun_GalaxyRay = { -0.729, -0.484, -2.753, 0.729, 1.265, 0.346, 'gun', muzzle = { 0, 0.604, -2.753 } },
	Gun_InfernoCannon = { -0.443, -0.437, -2.957, 0.443, 1.249, 0.828, 'gun', muzzle = { 0, 0.786, -2.957 } },
	Gun_Frostbite = { -0.265, -0.409, -2.688, 0.307, 1.499, 1.152, 'gun', muzzle = { 0, 0.503, -2.688 } },
	Gun_RoyalCrown = { -0.555, -0.421, -2.851, 0.555, 1.067, 0.949, 'gun', muzzle = { 0, 0.663, -2.851 } },
}
local ReplicatedStorage = game:GetService('ReplicatedStorage')
local Selection = game:GetService('Selection')
local ChangeHistory = game:GetService('ChangeHistoryService')

-- the item id a MeshPart belongs to: the longest id that is its name or the start of its name followed by "_"
-- (falls back to the name of a Model it sits in, in case the importer renamed the part)
local function idOf(mp)
	local best
	local function try(name)
		for id in DESIGN do
			if name == id or (name:sub(1, #id + 1) == id .. '_') then
				if not best or #id > #best then best = id end
			end
		end
	end
	try(mp.Name)
	local a = mp.Parent
	while not best and a and a ~= workspace and a ~= game do
		try(a.Name)
		a = a.Parent
	end
	return best
end

local roots = Selection:Get()
if #roots == 0 then roots = { workspace } end
local found = {}
for _, root in roots do
	local list = root:GetDescendants()
	if root:IsA('MeshPart') then table.insert(list, root) end
	for _, d in list do
		if d:IsA('MeshPart') and not d:IsDescendantOf(ReplicatedStorage) then
			local id = idOf(d)
			if id then table.insert(found, { d, id }) end
		end
	end
end
if #found == 0 then
	warn('[HoodItemMeshes] no imported items found. Import the Items_*.glb files first (MESH_IMPORT.md step 1), then run this again.')
	return
end

local _, recording = pcall(function() return ChangeHistory:TryBeginRecording('HoodItemMeshes setup') end)
local folder = ReplicatedStorage:FindFirstChild('HoodItemMeshes')
if not folder then
	folder = Instance.new('Folder')
	folder.Name = 'HoodItemMeshes'
	folder.Parent = ReplicatedStorage
end
local items, containers = {}, {}
local function item(id)
	if items[id] then return items[id] end
	local old = folder:FindFirstChild(id)
	if old then old:Destroy() end
	local m = Instance.new('Model')
	m.Name = id
	m.Parent = folder
	items[id] = m
	return m
end
local glowCount, untextured = 0, {}
for _, pair in found do
	local mp, id = pair[1], pair[2]
	local d = DESIGN[id]
	local top = mp.Parent
	while top and top.Parent and top.Parent ~= workspace and top.Parent ~= game do top = top.Parent end
	if top and top ~= mp and top.Parent == workspace then containers[top] = true end
	local hex = mp.Name:match('_Glow_(%x%x%x%x%x%x)$')
	if hex then
		-- glow: plain Neon in its colour (a texture would stop it glowing)
		for _, c in mp:GetChildren() do
			if c:IsA('SurfaceAppearance') or c:IsA('Decal') or c:IsA('Texture') then c:Destroy() end
		end
		pcall(function() mp.TextureID = '' end)
		mp.Color = Color3.fromHex(hex)
		mp.Material = Enum.Material.Neon
		mp.CastShadow = false
		glowCount += 1
	else
		-- body: keep the palette texture (TextureID or a SurfaceAppearance, whichever the importer made)
		local textured = mp:FindFirstChildWhichIsA('SurfaceAppearance') ~= nil
		pcall(function() textured = textured or mp.TextureID ~= '' end)
		if not textured then table.insert(untextured, mp.Name) end
		mp.Color = Color3.new(1, 1, 1)
		mp.Material = Enum.Material.SmoothPlastic
		mp.CastShadow = true
	end
	mp.Reflectance, mp.Transparency = 0, 0
	mp.Anchored = true
	local class = d[7]
	if class == 'solid' then
		mp.CanCollide, mp.CanTouch, mp.CanQuery = not hex, false, true
		pcall(function() mp.CollisionFidelity = Enum.CollisionFidelity.Box end)
	else
		mp.CanCollide, mp.CanTouch, mp.CanQuery = false, false, false
		pcall(function() mp.CollisionFidelity = Enum.CollisionFidelity.Box end)
	end
	if class == 'gun' then mp.Massless = true end
	pcall(function() mp.DoubleSided = false end)
	mp.Parent = item(id)
end

local made, parts = 0, 0
for id, m in items do
	local d = DESIGN[id]
	m:SetAttribute('DesignMin', Vector3.new(d[1], d[2], d[3]))
	m:SetAttribute('DesignMax', Vector3.new(d[4], d[5], d[6]))
	m:SetAttribute('Collision', d[7])
	if d.muzzle then m:SetAttribute('Muzzle', Vector3.new(d.muzzle[1], d.muzzle[2], d.muzzle[3])) end
	m:SetAttribute('ItemMesh', true)
	local cf, size = m:GetBoundingBox()
	m.WorldPivot = cf - Vector3.new(0, size.Y / 2, 0)
	-- the import must keep the design's proportions (World Forward = Front, World Up = Top)
	local ds = Vector3.new(d[4] - d[1], d[5] - d[2], d[6] - d[3])
	local k = size.Y / math.max(ds.Y, 1e-3)
	if math.abs(size.X / math.max(ds.X * k, 1e-3) - 1) > 0.08 or math.abs(size.Z / math.max(ds.Z * k, 1e-3) - 1) > 0.08 then
		warn(('[HoodItemMeshes] %s came in turned or stretched. Delete HoodItemMeshes, re-import with World Forward = Front and World Up = Top, run this again.'):format(id))
	end
	if d.colliders then
		-- walk-through items (the gate's opening): the mesh does not collide, invisible boxes do
		for _, p in m:GetChildren() do
			if p:IsA('BasePart') then p.CanCollide = false end
		end
		local dc = Vector3.new(d[1] + d[4], d[2] + d[5], d[3] + d[6]) / 2
		for _, c in d.colliders do
			local box = Instance.new('Part')
			box.Name = 'Collider'
			box.Size = Vector3.new(c[4], c[5], c[6]) * k
			box.CFrame = cf * CFrame.new((Vector3.new(c[1], c[2], c[3]) - dc) * k)
			box.Transparency = 1
			box.Anchored, box.CanCollide, box.CanTouch, box.CanQuery, box.CastShadow = true, true, false, true, false
			box.Parent = m
		end
	end
	made += 1
	for _, p in m:GetChildren() do
		if p:IsA('BasePart') then parts += 1 end
	end
end
for c in containers do
	local left = 0
	for _, x in c:GetDescendants() do
		if x:IsA('BasePart') then left += 1 end
	end
	if left == 0 then c:Destroy() end
end
local total, missing = 0, {}
for id in DESIGN do
	total += 1
	if not folder:FindFirstChild(id) then table.insert(missing, id) end
end
table.sort(missing)
if recording then pcall(function() ChangeHistory:FinishRecording(recording, Enum.FinishRecordingOperation.Commit) end) end
print(('[HoodItemMeshes] done: %d items (%d MeshParts, %d glowing) in ReplicatedStorage.HoodItemMeshes'):format(made, parts, glowCount))
if #missing > 0 then
	print(('[HoodItemMeshes] still to import (%d of %d): %s'):format(#missing, total, table.concat(missing, ', ')))
else
	print(('[HoodItemMeshes] all %d items are in. Now File > Save to Roblox.'):format(total))
end
if #untextured > 0 then
	warn(('[HoodItemMeshes] %d parts came in without their colour texture (they look white), e.g. %s. See MESH_IMPORT.md "If something looks wrong".'):format(#untextured, untextured[1]))
end
